const { withAppBuildGradle } = require('@expo/config-plugins');

/**
 * Keep Android release builds split per ABI instead of producing one universal
 * APK with every native library. `android/` is generated by Expo prebuild, so
 * the change lives in a config plugin rather than only in build.gradle.
 *
 * arm64-v8a covers the phone; x86_64 covers the emulator. Add more ABIs here
 * only if a real device needs them.
 */
const ABI_SPLITS = `    splits {
        abi {
            enable true
            reset()
            include 'arm64-v8a', 'x86_64'
            universalApk false
        }
    }
`;

module.exports = function withAndroidAbiSplits(config) {
  return withAppBuildGradle(config, (mod) => {
    if (mod.modResults.language !== 'groovy') return mod;
    const contents = mod.modResults.contents;
    if (contents.includes('splits {')) return mod;

    const marker = '    androidResources {';
    if (!contents.includes(marker)) return mod;

    mod.modResults.contents = contents.replace(marker, `${ABI_SPLITS}${marker}`);
    return mod;
  });
};
